<?php namespace BinerMail;
class Cpanel{private array $c;function __construct(){$this->c=require __DIR__.'/../config/cpanel.php';}private function call(string $module,string $function,array $params=[]):array{$url="https://{$this->c['host']}:{$this->c['port']}/execute/".rawurlencode($module).'/'.rawurlencode($function).'?'.http_build_query($params);$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Authorization: cpanel '.$this->c['user'].':'.$this->c['token'],'Accept: application/json'],CURLOPT_TIMEOUT=>20,CURLOPT_SSL_VERIFYPEER=>$this->c['verify_ssl'],CURLOPT_SSL_VERIFYHOST=>$this->c['verify_ssl']?2:0]);$raw=curl_exec($ch);if($raw===false)throw new \RuntimeException(curl_error($ch));$data=json_decode($raw,true);curl_close($ch);if(!is_array($data)||($data['status']??0)!==1)throw new \RuntimeException($data['errors'][0]??'cPanel API failed');return $data['data']??[];}public function create(string $local,string $password,int $quota=1024):array{return $this->call('Email','add_pop',['email'=>$local,'password'=>$password,'quota'=>$quota,'domain'=>config('domain')]);}public function changePassword(string $local,string $password):array{return $this->call('Email','passwd_pop',['email'=>$local,'password'=>$password,'domain'=>config('domain')]);}public function delete(string $local):array{return $this->call('Email','delete_pop',['email'=>$local,'domain'=>config('domain')]);}}
